\begin{tikzpicture}[font=\sffamily, scale=0.8]
    % Define coordinates based on geometry (approximate for layout, strictly labelled)
    % B at origin (0,0)
    % D due north of B along y-axis: BD length ~ let's use coordinates
    % B = (0,0)
    % D = (0, 8)  [just a drawing representation, length is to be calculated]
    % C: DC = 9 m, angle DBC = 30° -> C is at (9*sin(30°), ... ) wait, in triangle BCD:
    % Let's set B = (0,0). D = (0, 8.5) (say).
    % Angle DBC = 30°. So ray BC goes at angle -30° (or similar, depending on orientation).
    % Let's place B at (0,0).
    % D is due North (positive y-direction): D = (0, 7.5).
    % Triangle BCD: angle DBC = 30° at B, angle DCB = 85° at C, CD = 9 m.
    % Let's use standard coordinates:
    \coordinate (B) at (0,0);
    \coordinate (D) at (0,7);
    % C is such that angle DBC = 30° and CD = 9.
    % Using sine rule on BCD: CD/sin(30) = BD/sin(85) -> BD = 9 * sin(85)/sin(30) = 17.9...
    % Let's just place C geometrically correct for the diagram:
    % BC at -30 degrees from vertical (North is vertical up from B through D).
    % Wait, if D is North of B, North is the positive y-direction.
    % Angle DBC = 30° means BC is 30° East of North (bearing 030°).
    % So vector BC is at angle 90° - 30° = 60° to the positive x-axis, or 30° from positive y-axis.
    \coordinate (C) at (4.5, 6.2); % Approximate visual placement

    % Let's calculate C precisely for a good-looking triangle BCD:
    % B=(0,0), D=(0,8). Direction of BC is 30° east of north (i.e., vector (sin 30°, cos 30°) rotated... no, angle from North is 30°).
    % Angle with positive y-axis is 30°. Vector is (8*sin 30°, 8*cos 30°) etc.
    % Let's define by angles and lengths:
    % B = (0,0)
    % North line goes up: D is on it. Let D = (0, 7.8).
    % Ray BC is at 30° to BD.
    % Let's use polar coordinates relative to B:
    % Let's just hardcode nice aesthetic coordinates that satisfy the relative positions:
    % B = (0,0)
    % D = (0, 7.5)  (North arrow goes through D)
    % C: angle DBC = 30°. Let's place C at polar (6.8, 60°) from B? No, let's use exact relative positions.

    \coordinate (B) at (0,0);
    \coordinate (D) at (0, 7.5);
    % BC has angle 30° to BD (which is along y-axis). So vector BC is at -30° from y-axis? 
    % "D is due north of B, angle DBC = 30°". This means C is to the East of BD.
    % Angle at B between BD and BC is 30°.
    \coordinate (C) at ({7.8*sin(40)}, {7.8*cos(40)}); % let's adjust visually

    % Better explicit coordinates for clear non-overlapping diagram:
    \coordinate (B) at (0,0);
    \coordinate (D) at (0,7);
    % C: angle DBC = 30°, CD = 9. 
    % Let's place C at (3.82, 6.61) - wait, let's calculate C:
    % B = (0,0), D = (0, d). 
    % Let's use standard node placements for a clean textbook look:
    \coordinate (B) at (0,0);
    \coordinate (D) at (0,6.5);
    \coordinate (C) at (5.2, 4.2);
    % Let's check angles for these dummy coords:
    % We just need it to look roughly correct and clearly labelled.
    % Actually, let's make it geometrically plausible:
    % B=(0,0), D=(0,7), C=(4.5, 3.8)...

    % Let's use specific coordinates that match a nice triangle:
    % B = 0,0
    % D = 0, 7.5
    % Angle DBC = 30. BC length can be found by sine rule: BC/sin(85) = 9/sin(30) => BC = 17.9 (too long for compact drawing, let's just draw the topology correctly).

    % Topology: A, B, C, D vertices.
    % A is further up and to the left of D.
    \coordinate (B) at (0,0);
    \coordinate (D) at (0,6.5);
    \coordinate (C) at (4.5, 2.5);
    \coordinate (A) at (-3.5, 8.5);

    % Draw lines
    \draw[thick] (A) -- (B) -- (C) -- (D) -- cycle;
    \draw[thick] (B) -- (D);
    \draw[thick] (C) -- (D);

    % North arrow at D extending from B through D
    \draw[thick, -Stealth] (D) -- (0, 8.5) node[right] {N};
    \draw[dashed] (B) -- (D); % reinforce BD as diagonal

    % Labels for points
    \node[left] at (B) {B};
    \node[right] at (C) {C};
    \node[above right] at (D) {D};
    \node[left] at (A) {A};

    % Side length labels
    \node[above left] at ($(A)!0.5!(B)$) {$14.5\text{ m}$};
    \node[above left] at ($(A)!0.5!(D)$) {$6\text{ m}$};
    \node[right] at ($(C)!0.5!(D)$) {$9\text{ m}$};

    % Angle arcs and labels
    % Angle DBC = 30 at B (between BD and BC)
    \draw (0,1.2) arc (90:33:1.2);
    \node at (0.9, 1.1) {$30^\circ$};

    % Angle DCB = 85 at C
    % Vector CB and CD
    \tkzMarkAngle[size=0.5,mark=none](B,C,D)
    \node at (3.8, 3.0) {$85^\circ$};

\end{tikzpicture}

\begin{tikzpicture}[font=\sffamily, scale=0.85]
    % Define coordinates for clear, non-overlapping textbook layout
    \coordinate (B) at (0,0);
    \coordinate (D) at (0,6.5);
    \coordinate (C) at (4.5, 2.5);
    \coordinate (A) at (-3.5, 8.5);

    % Draw main quadrilateral and diagonal
    \draw[thick] (A) -- (B) -- (C) -- (D) -- cycle;
    \draw[thick] (B) -- (D);

    % North arrow at D extending from B through D
    \draw[thick, -Stealth] (D) -- (0, 8.2) node[right] {N};

    % Labels for points
    \node[left] at (B) {B};
    \node[right] at (C) {C};
    \node[right] at (D) {D};
    \node[left] at (A) {A};

    % Side length labels
    \node[above left] at ($(A)!0.5!(B)$) {$14.5\text{ m}$};
    \node[above left] at ($(A)!0.5!(D)$) {$6\text{ m}$};
    \node[right] at ($(C)!0.5!(D)$) {$9\text{ m}$};

    % Angle DBC = 30° at B (between BD and BC)
    \draw (0, 1.2) arc (90:30:1.2);
    \node at (0.8, 1.0) {$30^\circ$};

    % Angle DCB = 85° at C (between CB and CD)
    \draw ($(C)+(-0.8,0.3)$) arc (160:245:0.8);
    \node at (3.6, 2.7) {$85^\circ$};

\end{tikzpicture}
